def move_prices_to_history(apps, schema_editor):
    """Each priced product's list_price becomes its first dated price, in effect since the product
    was created; existing registration items that used that amount are linked to it. A list price
    of 0.00 meant "no price yet", so it creates no record."""
    Product = apps.get_model("registrations", "Product")
    ProductPrice = apps.get_model("registrations", "ProductPrice")
    RegistrationItem = apps.get_model("registrations", "RegistrationItem")
    for product in Product.objects.filter(list_price__gt=0):
        price = ProductPrice.objects.create(
            product=product,
            unit_price=product.list_price,
            currency=product.currency,
            effective_from=product.created_at,
            reason="Price carried over from the catalog when price history started.",
        )
        RegistrationItem.objects.filter(
            product=product, list_unit_price_snapshot=product.list_price
        ).update(price_version=price)


def restore_list_prices(apps, schema_editor):
    """Going back: list_price returns as each product's latest price already in effect."""
    Product = apps.get_model("registrations", "Product")
    ProductPrice = apps.get_model("registrations", "ProductPrice")
    for product in Product.objects.all():
        price = (
            ProductPrice.objects.filter(
                product=product, effective_from__lte=django.utils.timezone.now()
            )
            .order_by("-effective_from", "-id")
            .first()
        )
        if price:
            product.list_price = price.unit_price
            product.save(update_fields=["list_price"])


